});

var packageText = (V8.Form && V8.Form.AppPakcet) ? V8.Form.AppPakcet : '';
if (!packageText) {
  V8.Tips('请先点击【开始制作】生成数据包。', false);
  return;
}
var packageName = V8.Form.AppName || V8.Form.PackageName || 'Microi应用包';
var packageVersion = V8.Form.AppVersion || V8.Form.PackageVersion || '1.0.0';
var safeFileName = function (name) {
  return String(name || 'microi-store-package')
    .replace(/[\/:*?"<>|]+/g, '_')
    .replace(/\s+/g, '_')
    .replace(/^_+|_+$/g, '') || 'microi-store-package';
};
try {
  if (typeof packageText != 'string') {
    packageText = JSON.stringify(packageText, null, 2);
  } else {
    packageText = JSON.stringify(JSON.parse(packageText), null, 2);
  }
  var blob = new Blob([packageText], { type: 'application/json;charset=utf-8' });
  var url = URL.createObjectURL(blob);
  var link = document.createElement('a');
  link.href = url;
  link.download = safeFileName(packageName + '-' + packageVersion) + '.json';
  document.body.appendChild(link);
  link.click();
  setTimeout(function () {
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }, 0);
  V8.Tips('离线数据包已开始下载。', true);
} catch (error) {
  V8.Tips('下载失败：数据包不是有效 JSON。' + error.message, false);
}

var pickList = function (value) {
  if (!value) { return []; }
  if (Array.isArray(value)) { return value; }
  if (typeof value == 'string') {
    try {
      var parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }
  return [];
};
var pickValues = function (list, fieldName) {
  var result = [];
  for (var i = 0; i < list.length; i++) {
    var row = list[i] || {};
    var value = row[fieldName] || row.Id || row.id || row.Value;
    if (value) { result.push(value); }
  }
  return result;
};
var setFormValue = function (fieldName, value) {
  V8.FormSet(fieldName, value);
  if (V8.Form) { V8.Form[fieldName] = value; }
};

var MenuIds = pickValues(pickList(V8.Form.SelectMenu), 'Id');
var TableIds = pickValues(pickList(V8.Form.SelectTable), 'Id');
var FlowIds = pickValues(pickList(V8.Form.SelectWF), 'Id');
var ApiEngineKeys = pickValues(pickList(V8.Form.SelectApiEngine), 'ApiEngineKey');
var selectedAiApps = pickList(V8.Form.SelectAiApp);
var AiAppIds = pickValues(selectedAiApps, 'AppId');
var preparedAssets = pickList(V8.Form.AiAppPackageManifest);
var DataSelections = pickList(V8.Form.SelectData);
var applicationType = String(V8.Form.ApplicationType || 'Regular');
var isPlatformPackage = applicationType == 'Platform' || applicationType == 'Regular';
var isStandaloneAiApplication = applicationType == 'Web' || applicationType == 'UniApp' || applicationType == 'MicroService';
var packageName = V8.Form.AppName || V8.Form.PackageName || 'Microi应用包';
var packageVersion = V8.Form.AppVersion || V8.Form.PackageVersion || '1.0.0';
var packageData = null;

if (!isPlatformPackage && !isStandaloneAiApplication) {
  V8.Tips('不支持的应用类型：' + applicationType + '。', false);
  return;
}

if (isStandaloneAiApplication) {
  if (AiAppIds.length != 1) {
    V8.Tips('发布' + applicationType + '应用时，必须且只能选择1个AI应用。', false);
    return;
  }
  var selectedAiApp = selectedAiApps[0] || {};
  var selectedApplicationType = selectedAiApp.AppType || selectedAiApp.ApplicationType || '';
  if (selectedApplicationType && String(selectedApplicationType) != applicationType) {
    V8.Tips('选择的AI应用类型为' + selectedApplicationType + '，与当前应用类型' + applicationType + '不一致。', false);
    return;
  }
  var aiPackageResult = await V8.ApiEngine.Run('ai_app_publish_store', {
    Action: 'PackageOnly',
    AppId: AiAppIds[0],
    AppVersion: packageVersion,
    AppName: packageName,
    AppDetail: V8.Form.AppDetail || '',
    MenuIds: MenuIds,
    TableIds: TableIds,
    FlowIds: FlowIds,
    ApiEngineKeys: ApiEngineKeys,
    IncludeSource: !!selectedAiApp.IncludeSource,
    PreparedAssets: preparedAssets.length ? preparedAssets[0] : null,
    DataSelections: DataSelections
  });
  if (!aiPackageResult || aiPackageResult.Code != 1 || !aiPackageResult.Data || !aiPackageResult.Data.Package) {
    V8.Tips('AI应用制作失败：' + ((aiPackageResult && aiPackageResult.Msg) || '接口无返回'), false);
    return;
  }
  packageData = aiPackageResult.Data.Package;
  var packageInfo = packageData.PackageInfo || {};
  if (String(packageInfo.ApplicationType || '') != applicationType) {
    V8.Tips('AI应用实际类型与当前选择不一致，请重新选择。', false);
    return;
  }
  setFormValue('AppId', packageInfo.AppId || '');
