  setFormValue('AppVersion', packageInfo.AppVersion || packageInfo.Version || packageVersion);
} else {
  if (MenuIds.length == 0 && TableIds.length == 0 && FlowIds.length == 0 && ApiEngineKeys.length == 0 && AiAppIds.length == 0 && DataSelections.length == 0) {
    V8.Tips('请至少选择1个菜单、流程、接口引擎、表单、AI应用或数据集！', false);
    return;
  }
