/*
 * V8 ApiEngine
 * ApiEngineKey: ai_app_build_file
 * Version: v1.0.9
 * Function:
 * - 统一使用 sys_microistore 作为应用主表；mci_ai_app_file 与 mci_ai_app_version 继续保存私有源码和构建版本。
 */

function ok(data, msg) { return { Code: 1, Data: data || null, Msg: msg || '成功' }; }
function fail(msg, data) { return { Code: 0, Data: data || null, Msg: msg || '执行失败' }; }
function text(value, fallback) { return value === null || value === undefined ? (fallback || '') : String(value); }
function isBlank(value) { return text(value).replace(/^\s+|\s+$/g, '') === ''; }
function toArray(value) { var list = []; if (!value || value.length === undefined) return list; for (var i=0;i<value.length;i++) list.push(value[i]); return list; }
function normalizePath(value) {
  var path = text(value).replace(/\\/g,'/').replace(/^\/+|\/+$/g,'');
  var parts = path.split('/'), safe=[];
  for(var i=0;i<parts.length;i++){ if(!parts[i]||parts[i]==='.'||parts[i]==='..') continue; safe.push(parts[i].replace(/[:*?"<>|]/g,'_')); }
  return safe.join('/');
}
function isTextPath(path) {
  var lower=text(path).toLowerCase();
  return /\.(html?|css|scss|sass|less|js|jsx|mjs|cjs|ts|tsx|json|map|xml|txt|md|svg|yaml|yml|toml|ini)$/.test(lower);
}
function currentUser() {
  var user=V8.CurrentUser||{};
  if(!user||isBlank(user.Id)){ var token=V8.Method.GetCurrentToken?V8.Method.GetCurrentToken():null; if(token&&token.CurrentUser) user=token.CurrentUser; }
  return user||{};
}
function getApp(appId) { return V8.FormEngine.GetFormData('sys_microistore',{_Where:[['Id','=',appId]],_PageSize:1}); }
function getService(appKey) { return V8.FormEngine.GetFormData('sys_microiservice',{_Where:[['MsKey','=',appKey]],_PageSize:1}); }
function assertCanEdit(app) {
  var user=currentUser(), level=parseInt(user.Level||0,10);
  if(level>=9999) return;
  if(isBlank(user.Id)||text(app.OwnerUserId)!==text(user.Id)) throw new Error('无权查看或修改该应用编译文件');
}
function publicUrl(path) {
  if(/^https?:\/\//i.test(text(path))) return text(path);
  var result=V8.Method.GetPrivateFileUrl({OsClient:V8.OsClient,FilePathName:path,Limit:false});
  if(!result||result.Code!==1) throw new Error('获取编译文件地址失败：'+path);
  var data=result.Data||{};
  return typeof data==='string'?data:text(data.Url||data.url||data.FileUrl||data.FullPath||data.Path);
}
function findAsset(assets,path) {
  var target=normalizePath(path).toLowerCase();
  for(var i=0;i<assets.length;i++){ if(normalizePath(assets[i].Path||assets[i].RelativePath||assets[i].FileName).toLowerCase()===target) return {Asset:assets[i],Index:i}; }
  return null;
}
var appId=text(V8.Param.AppId);
if(isBlank(appId)) return fail('AppId不能为空');
var appResult=getApp(appId);
if(!appResult||appResult.Code!==1||!appResult.Data) return {Code:2,Data:null,Msg:'AI应用不存在'};
var app=appResult.Data;
try{assertCanEdit(app);}catch(authError){return fail(authError.message);}
var action=text(V8.Param.Action||'List');
if(text(app.AppType)==='MicroService'){
  var serviceResult=getService(app.AppKey);
  if(!serviceResult||serviceResult.Code!==1||!serviceResult.Data) return fail('未找到微服务编译记录');
