        // ==================== 步骤3.5：发现子表控件（TableChild）关联的菜单 ====================
        // 查询当前已收集的tableIds对应的字段，找到Component='TableChild'的字段
        // 从其Config中提取TableChildSysMenuId，将对应的菜单及其子菜单也加入导出范围

        if (tableIds.length > 0) {
