    // ==================== 步骤8：固化用户选择的数据 ====================

    var exportDataSets = [];
    var exportDataRowCount = 0;
    var allowedDataOperators = {
        '=': true, '==': true, 'Equal': true, '<>': true, '!=': true, 'NotEqual': true,
        '>': true, '>=': true, '<': true, '<=': true,
        'Like': true, 'NotLike': true, 'StartLike': true, 'EndLike': true,
