        }
        applicationBundles.push(aiPackage.ApplicationBundle);
        applicationPackages.push(aiPackage);
    }
    debugLog.applicationBundleCount = applicationBundles.length;

    // ==================== 步骤9：组装数据包 ====================

    var packageData = {
        PackageInfo: {
            Name: PackageName,
            Version: PackageVersion,
