  var compare = latest && local ? compareVersion(latest, local) : 0;
  app.StoreInstallStatus = compare > 0 ? "Outdated" : (compare < 0 ? "Abnormal" : "Installed");
  app.StoreInstallStatusText = compare > 0 ? "可更新" : (compare < 0 ? "版本异常" : "已安装");
