    if (item.StoreInstallStatus !== "Uninstalled") installedCount++;
    if (item.StoreInstallStatus === "Uninstalled") {
      notices.push({
        Status: item.StoreInstallStatus,
        AppId: item.AppId,
        StoreId: item.Id,
